// 1. Exact String Match (Case-Sensitive)
Raw_Bike
| where Neighbourhood == "Mile End"

// 2. Exact String Match (Case-Insensitive - try not to use not recommended, unless needed)
Raw_Bike
| where Neighbourhood =~ "mile end"

// 3. String Has
Raw_Bike
| where Street has "End"

// 4. String Contains (Less Recommended - see KQL best Practices)
Raw_Bike
| where Street contains "End"

// 5. String endswith 
Raw_Bike
| where Neighbourhood startswith "West"

// 6. String endswith 
Raw_Bike
| where BikepointID endswith "649"

// 7. String Not Equal 
Raw_Bike
| where No_Bikes != "West End"

// 8. Integer Equality - empty bike racks 
Raw_Bike
| where No_Bikes == 0

// 9. Integer less than or equal to (bikes running out!)
Raw_Bike
| where No_Bikes <= 3

// 10. Integer greater than (lots of space, consider moving bikes)
Raw_Bike
| where No_Empty_Docks > 30 

// 11. Numeric ranges - using the (X .. Y) syntax
Raw_Bike
| where Latitude between (51.461 .. 51.472)

// 12. Dateime equality (exact match)
Raw_Bike
| where ingestion_time() == datetime(2025-02-17 10:00:00)

// 13. Date/Time Range (After a specific date/time)
Raw_Bike
| where ingestion_time() > datetime(2025-02-18 10:15:00)

// 14. Using ago() in datetime filtering 
Raw_Bike
| where ingestion_time() > ago(24h)

// 15. Using between, ago() and now() 
Raw_Bike
| where ingestion_time() between (ago(24h) .. now())

// 16. Records ingested yesterday
Raw_Bike
| where ingestion_time() between (startofday(ago(1d)) .. endofday(ago(1d)))

// 17. Multiple Conditions (AND)
Raw_Bike
| where Neighbourhood == "Mile End" and No_Bikes > 5

// 18. Multiple Conditions (OR)
Raw_Bike
| where Neighbourhood == "Mile End" or No_Bikes > 5

// 19. Using 'in' operator for multiple string matches
Raw_Bike
| where Neighbourhood in ("Mile End", "Sands End")

// 20. Negating a filter with 'not'
Raw_Bike
| where not (Neighbourhood in ("Mile End", "Sands End"))
